<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/platform-admin-security.php';
$admin=platform_admin_require();$pdo=app_db();
if(empty($_SESSION['platform_master_csrf']))$_SESSION['platform_master_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['platform_master_csrf'];$flash='';$error='';
$views=['overview','producers','affiliates','products','sales','documents','logs','admin-audit','intelligence','security','settings','saas'];
$view=(string)($_GET['view']??'overview');if(!in_array($view,$views,true))$view='overview';
if(empty($_SESSION['platform_request_id']))$_SESSION['platform_request_id']=bin2hex(random_bytes(16));
if(in_array($view,['sales','admin-audit','security','settings','documents'],true))platform_admin_audit('admin.sensitive.viewed','success','master-view',$view);
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){platform_admin_audit('admin.csrf.rejected','denied','admin-page','',['view'=>$view]);http_response_code(403);exit('Sessão expirada. Atualize a página.');}
    $action=(string)($_POST['action']??'');
    try{
        if($action==='logout') { platform_admin_audit('admin.auth.logout','success','admin',(string)$admin['id']);unset($_SESSION['platform_admin_id'],$_SESSION['platform_admin_last_activity']);session_regenerate_id(true);header('Location: platform-admin-login.php');exit; }
        elseif($action==='account_status'){
            $userId=trim((string)($_POST['user_id']??''));$status=(string)($_POST['status']??'');$reason=trim((string)($_POST['reason']??''));
            if($userId===''||!in_array($status,['active','suspended','blocked'],true)||strlen($reason)<8||strlen($reason)>500||($_POST['confirm']??'')!=='yes')throw new DomainException('Confirme a ação e informe uma justificativa de 8 a 500 caracteres.');
            $q=$pdo->prepare('SELECT id,name,email,account_status FROM users WHERE id=?');$q->execute([$userId]);$target=$q->fetch();if(!$target)throw new DomainException('Usuário não encontrado.');
            $pdo->beginTransaction();$pdo->prepare('UPDATE users SET account_status=? WHERE id=?')->execute([$status,$userId]);$pdo->prepare('UPDATE api_access_tokens SET revoked_at=UTC_TIMESTAMP() WHERE user_id=? AND revoked_at IS NULL')->execute([$userId]);$pdo->prepare('UPDATE affiliate_api_access_tokens SET revoked_at=UTC_TIMESTAMP() WHERE user_id=? AND revoked_at IS NULL')->execute([$userId]);
            platform_admin_audit('admin.user.status_changed','success','user',$userId,['before'=>$target['account_status'],'after'=>$status,'reason'=>$reason]);$pdo->commit();platform_admin_audit_release_lock();$flash='Situação da conta atualizada.';
        }elseif($action==='alert_review'){
            $id=(string)($_POST['alert_id']??'');$status=(string)($_POST['status']??'');$note=trim((string)($_POST['note']??''));
            if(!in_array($status,['open','investigating','legitimate','false_positive','resolved'],true)||strlen($note)<5||strlen($note)>2000)throw new DomainException('Escolha um status e registre uma observação de pelo menos 5 caracteres.');
            $q=$pdo->prepare('UPDATE platform_admin_alerts SET status=?,analyst_note=?,reviewed_by=?,reviewed_at=UTC_TIMESTAMP() WHERE id=?');$q->execute([$status,$note,$admin['id'],$id]);if(!$q->rowCount())throw new DomainException('Alerta não encontrado ou sem alterações.');
            platform_admin_audit('admin.alert.reviewed','success','alert',$id,['status'=>$status,'note'=>$note]);$flash='Investigação registrada.';
        }else throw new DomainException('Ação administrativa inválida.');
    }catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();try{platform_admin_audit_release_lock();}catch(Throwable $ignored){}$error=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();try{platform_admin_audit_release_lock();}catch(Throwable $ignored){}$error='Não foi possível concluir a ação administrativa.';try{platform_admin_audit('admin.operation.failed','failure',$action,'',['view'=>$view]);}catch(Throwable $ignored){}}
}

function pmae($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function pma_count(PDO $pdo,string $sql,array $params=[]):int{$q=$pdo->prepare($sql);$q->execute($params);return (int)$q->fetchColumn();}
function pma_money($value):string{return 'R$ '.number_format((float)$value,2,',','.');}
function pma_csv_row($out,array $row):void{foreach($row as &$value){if(is_string($value)&&preg_match('/^[\s]*[=+\-@]/u',$value))$value="'".$value;}unset($value);fputcsv($out,$row,';');}

if($view==='intelligence'){
    $failures=$pdo->query("SELECT actor_email,COUNT(*) AS total,MAX(created_at) AS last_at FROM platform_admin_audit WHERE event_type='admin.auth.password_failed' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 15 MINUTE) GROUP BY actor_email HAVING COUNT(*)>=5")->fetchAll();
    foreach($failures as $failure){$bucket=(string)(intdiv(time(),900)*900);$fingerprint=hash('sha256','admin-login-failures|'.$failure['actor_email'].'|'.$bucket);$id='alert-'.substr($fingerprint,0,40);$insert=$pdo->prepare("INSERT IGNORE INTO platform_admin_alerts(id,fingerprint,priority,category,title,reason,related_event_type) VALUES(?,?,'high','authentication','Tentativas repetidas de acesso administrativo',?,'admin.auth.password_failed')");$insert->execute([$id,$fingerprint,'Foram registradas '.$failure['total'].' tentativas de senha inválida para a mesma identificação em até 15 minutos. É um sinal para revisão, não confirmação de fraude.']);}
}

if(isset($_GET['export'])&&$_GET['export']==='logs'){
    if(!in_array($view,['logs','admin-audit'],true)){http_response_code(400);exit('Exportação inválida.');}
    platform_admin_audit('admin.audit.exported','success',$view,'',['format'=>'csv']);
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="affiliey-'.($view==='logs'?'business':'master-audit').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
    if($view==='logs'){$q=$pdo->query('SELECT l.id,l.created_at,l.actor_user_id,u.email,l.action_key,l.subject_type,l.subject_id,l.details FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_user_id ORDER BY l.created_at DESC LIMIT 10000');fputcsv($out,['id','created_at_utc','actor_user_id','actor_email','action','resource_type','resource_id','details'],';');}
    else{$q=$pdo->query('SELECT id,created_at,admin_id,actor_email,event_type,result,resource_type,resource_id,details,request_id,previous_hash,event_hash FROM platform_admin_audit ORDER BY id DESC LIMIT 10000');fputcsv($out,['id','created_at_utc','admin_id','actor_email','event_type','result','resource_type','resource_id','details','request_id','previous_hash','event_hash'],';');}
    while($row=$q->fetch())fputcsv($out,$row,';');fclose($out);exit;
}

$period=(string)($_GET['period']??'30');if(!in_array($period,['7','30','90'],true))$period='30';$q=trim((string)($_GET['q']??''));$like='%'.$q.'%';
$metrics=[];
if($view==='overview'){
    $metrics=[['Produtores',pma_count($pdo,"SELECT COUNT(DISTINCT tenant_id) FROM memberships WHERE role='owner'"),'Contas com espaço produtor'],['Afiliados vinculados',pma_count($pdo,"SELECT COUNT(DISTINCT user_id) FROM affiliate_account_links WHERE status='active'"),'Contas com vínculo ativo'],['Usuários cadastrados',pma_count($pdo,'SELECT COUNT(*) FROM users'),'Todas as contas'],['Novos cadastros',pma_count($pdo,'SELECT COUNT(*) FROM users WHERE created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL '.(int)$period.' DAY)'),'Últimos '.$period.' dias'],['Contas ativas',pma_count($pdo,"SELECT COUNT(*) FROM users WHERE account_status='active'"),'Usuários habilitados'],['Suspensas ou bloqueadas',pma_count($pdo,"SELECT COUNT(*) FROM users WHERE account_status<>'active'"),'Revisão administrativa'],['Produtos integrados',pma_count($pdo,"SELECT COUNT(*) FROM integration_products WHERE status='active'"),'Produtos ativos autorizados'],['Vendas registradas',pma_count($pdo,'SELECT COUNT(*) FROM sales_orders'),'Transações importadas'],['Faturamento registrado',pma_money((float)$pdo->query('SELECT COALESCE(SUM(amount_cents),0)/100 FROM sales_orders')->fetchColumn()),'Valor bruto sincronizado'],['Comissões registradas',pma_money((float)$pdo->query('SELECT COALESCE(SUM(commission_cents),0)/100 FROM sales_orders')->fetchColumn()),'Valor informado pelas integrações'],['Alertas em aberto',pma_count($pdo,"SELECT COUNT(*) FROM platform_admin_alerts WHERE status IN ('open','investigating')"),'Investigações pendentes'],['Eventos de segurança (24h)',pma_count($pdo,"SELECT COUNT(*) FROM platform_admin_audit WHERE result='denied' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 24 HOUR)"),'Acessos administrativos negados']];
}
$salesTrend=[];$trendMax=0;
if($view==='overview'){$salesTrend=$pdo->query('SELECT DATE(sold_at) AS sale_day,COUNT(*) AS orders,SUM(amount_cents)/100 AS revenue FROM sales_orders WHERE sold_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL '.(int)$period.' DAY) GROUP BY DATE(sold_at) ORDER BY sale_day ASC')->fetchAll();foreach($salesTrend as $day)$trendMax=max($trendMax,(float)$day['revenue']);}
$rows=[];$title='Visão geral';$subtitle='Indicadores reais disponíveis no banco AFFILIEY.';
if($view==='producers'){$title='Produtores';$subtitle='Contas produtoras e seus responsáveis, consultados no banco atual.';$s=$pdo->prepare("SELECT t.id,t.name,t.slug,t.created_at,u.id AS user_id,u.name AS owner_name,u.email,u.account_status FROM tenants t LEFT JOIN memberships m ON m.tenant_id=t.id AND m.role='owner' LEFT JOIN users u ON u.id=m.user_id WHERE (?='' OR t.name LIKE ? OR u.name LIKE ? OR u.email LIKE ?) ORDER BY t.created_at DESC LIMIT 300");$s->execute([$q,$like,$like,$like]);$rows=$s->fetchAll();}
if($view==='affiliates'){$title='Afiliados';$subtitle='Afiliados e relacionamento de contas vinculadas a produtores.';$s=$pdo->prepare('SELECT a.id,a.name,a.email,a.status,a.affiliate_group,a.created_at,t.name AS producer_name,l.user_id,u.account_status FROM affiliates a JOIN tenants t ON t.id=a.tenant_id LEFT JOIN affiliate_account_links l ON l.tenant_id=a.tenant_id AND l.affiliate_id=a.id AND l.status="active" LEFT JOIN users u ON u.id=l.user_id WHERE (?="" OR a.name LIKE ? OR a.email LIKE ? OR a.id LIKE ?) ORDER BY a.created_at DESC LIMIT 300');$s->execute([$q,$like,$like,$like]);$rows=$s->fetchAll();}
if($view==='products'){$title='Produtos';$subtitle='Produtos importados por conexões oficiais existentes.';$s=$pdo->prepare('SELECT p.id,p.external_product_id,p.name,p.status,p.created_at,t.name AS producer_name,c.platform,c.name AS connection_name FROM integration_products p JOIN tenants t ON t.id=p.tenant_id JOIN integration_connections c ON c.id=p.connection_id WHERE (?="" OR p.name LIKE ? OR p.external_product_id LIKE ? OR t.name LIKE ?) ORDER BY p.created_at DESC LIMIT 300');$s->execute([$q,$like,$like,$like]);$rows=$s->fetchAll();}
if($view==='sales'){$title='Vendas e comissões';$subtitle='Transações recebidas por integrações; valores permanecem vinculados ao produtor.';$s=$pdo->prepare('SELECT o.id,o.external_order_id,o.product_name,o.amount_cents,o.commission_cents,o.currency,o.status,o.sold_at,t.name AS producer_name,a.name AS affiliate_name,c.platform FROM sales_orders o JOIN tenants t ON t.id=o.tenant_id JOIN integration_connections c ON c.id=o.connection_id LEFT JOIN affiliates a ON a.tenant_id=o.tenant_id AND a.id=o.affiliate_id WHERE (?="" OR o.external_order_id LIKE ? OR o.product_name LIKE ? OR a.name LIKE ? OR t.name LIKE ?) ORDER BY o.sold_at DESC LIMIT 300');$s->execute([$q,$like,$like,$like,$like]);$rows=$s->fetchAll();}
if($view==='logs'||$view==='admin-audit'){$title=$view==='logs'?'Central de Logs':'Auditoria Administrativa';$subtitle=$view==='logs'?'Atividades de negócio gravadas pelos módulos existentes.':'Eventos administrativos encadeados por hash e registrados pelo backend.';if($view==='logs'){$s=$pdo->prepare('SELECT l.id,l.created_at,l.actor_user_id,l.action_key,l.subject_type,l.subject_id,l.details,u.name AS actor_name,u.email AS actor_email FROM audit_logs l JOIN users u ON u.id=l.actor_user_id WHERE (?="" OR l.action_key LIKE ? OR l.actor_user_id LIKE ? OR u.email LIKE ? OR l.subject_id LIKE ?) ORDER BY l.created_at DESC LIMIT 300');$s->execute([$q,$like,$like,$like,$like]);}else{$s=$pdo->prepare('SELECT id,created_at,admin_id,actor_email,event_type,result,resource_type,resource_id,details,request_id,previous_hash,event_hash FROM platform_admin_audit WHERE (?="" OR event_type LIKE ? OR actor_email LIKE ? OR resource_id LIKE ? OR admin_id LIKE ?) ORDER BY id DESC LIMIT 300');$s->execute([$q,$like,$like,$like,$like]);}$rows=$s->fetchAll();}
if($view==='intelligence'){$title='Inteligência e Alertas';$subtitle='Regras explícitas sinalizam padrões para revisão humana; não aplicam punições automáticas.';$rows=$pdo->query("SELECT a.*,u.name AS user_name,u.email AS user_email FROM platform_admin_alerts a LEFT JOIN users u ON u.id=a.related_user_id ORDER BY FIELD(a.priority,'critical','high','medium','low','informational'),a.created_at DESC LIMIT 200")->fetchAll();}
if($view==='security'){$title='Segurança';$subtitle='Sessões, acessos negados, tentativas administrativas e bloqueios do mecanismo de login.';$rows=$pdo->query("SELECT id,created_at,admin_id,actor_email,event_type,result,resource_type,resource_id,details FROM platform_admin_audit WHERE result='denied' OR event_type LIKE 'admin.auth.%' OR event_type LIKE 'admin.mfa.%' ORDER BY id DESC LIMIT 200")->fetchAll();$metrics=[['Tentativas de login bloqueadas',pma_count($pdo,'SELECT COUNT(*) FROM api_login_attempts WHERE locked_until>UTC_TIMESTAMP()'),'Chaves de tentativa ainda são anônimas no esquema atual'],['Acessos admin negados',pma_count($pdo,"SELECT COUNT(*) FROM platform_admin_audit WHERE result='denied' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 24 HOUR)"),'Últimas 24 horas'],['Sessões admin',pma_count($pdo,'SELECT COUNT(*) FROM platform_admins WHERE enabled=1 AND last_activity_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 20 MINUTE)'),'Atividade recente']];}
if($view==='documents'){$title='Aprovação de documentos';$tables=$pdo->query("SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name LIKE '%document%' ORDER BY table_name")->fetchAll(PDO::FETCH_COLUMN);$subtitle=$tables?'Há estruturas com nome relacionado a documentos, mas não há um fluxo de aprovação integrado com armazenamento privado.':'O esquema atual não contém módulo de upload, armazenamento privado ou status de documentos.';}
if($view==='settings'){$title='Configurações gerais';$subtitle='Resumo seguro da configuração efetiva; segredos não são exibidos nem editáveis nesta tela.';$rows=[['Configuração'=>'Banco de dados','Valor'=>'MySQL · '.(string)database_settings()['host'].' / '.(string)database_settings()['database']],['Configuração'=>'URL pública','Valor'=>(string)(getenv('VERTICE_APP_URL')?:'Não definida no servidor')],['Configuração'=>'Autenticação master','Valor'=>'Senha + TOTP obrigatório'],['Configuração'=>'Expiração por inatividade','Valor'=>'20 minutos'],['Configuração'=>'Logs administrativos','Valor'=>'Armazenamento encadeado por HMAC; sem edição pelo painel'],['Configuração'=>'Documentos','Valor'=>'Módulo de envio e retenção ainda não existe']];}
