?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= pmae($title) ?> — AFFILIEY Master</title><link rel="stylesheet" href="assets/css/platform-admin.css"><link rel="stylesheet" href="/assets/css/brand.css?v=affiliey4"><link rel="stylesheet" href="assets/css/platform-admin-master.css"></head><body class="master-shell"><aside class="master-sidebar"><a class="master-brand" href="platform-admin-master.php"><img src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"><span>MASTER CONTROL</span></a><nav aria-label="Administração master"><?php foreach($labels as $key=>$label): ?><a class="<?= $view===$key?'active':'' ?>" href="platform-admin-master.php?view=<?= pmae($key) ?>"><span class="nav-dot"></span><?= pmae($label) ?></a><?php endforeach; ?><a href="platform-admin.php"><span class="nav-dot"></span>Gestão SaaS legada</a></nav><div class="master-sidebar-foot">Acesso Super Admin · sessão protegida</div></aside><main class="master-main"><header class="master-top"><div><span class="eyebrow">AFFILIEY / MASTER CONTROL</span><span class="master-live"><i></i> MFA ativo</span></div><div class="master-user"><?= pmae($admin['name']) ?><form method="post"><input type="hidden" name="csrf" value="<?= pmae($csrf) ?>"><input type="hidden" name="action" value="logout"><button class="button small" type="submit">Sair</button></form></div></header><section class="master-content"><div class="master-heading"><div><p class="eyebrow"><?= $view==='overview'?'CENTRO DE COMANDO':'ADMINISTRAÇÃO' ?></p><h1><?= pmae($title) ?></h1><p><?= pmae($subtitle) ?></p></div><?php if($view==='overview'): ?><form method="get" class="period-form"><input type="hidden" name="view" value="overview"><label>Período<select name="period"><option value="7" <?= $period==='7'?'selected':'' ?>>7 dias</option><option value="30" <?= $period==='30'?'selected':'' ?>>30 dias</option><option value="90" <?= $period==='90'?'selected':'' ?>>90 dias</option></select></label><button class="button" type="submit">Aplicar</button></form><?php endif; ?></div>
