<?php if($view==='overview'): ?><section class="master-panel trend-panel"><div class="master-panel-head"><div><h2>Evolução de vendas</h2><p>Faturamento sincronizado por dia · últimos <?= (int)$period ?> dias</p></div><a href="platform-admin-master.php?view=sales">Ver transações</a></div><?php if(!$salesTrend): ?><p class="master-empty-inline">Ainda não há transações no período selecionado.</p><?php else: ?><div class="sales-trend" role="img" aria-label="Gráfico de faturamento diário no período selecionado"><?php foreach($salesTrend as $day): $barHeight=$trendMax>0?max(4,(int)round(((float)$day['revenue']/$trendMax)*100)):4; ?><div class="trend-column"><span class="trend-value"><?= pmae(pma_money((float)$day['revenue'])) ?> · <?= (int)$day['orders'] ?> vendas</span><div class="trend-bar" style="height:<?= $barHeight ?>%"></div><time><?= pmae(date('d/m',strtotime($day['sale_day']))) ?></time></div><?php endforeach; ?></div><?php endif; ?></section><div class="master-grid-two"><section class="master-panel"><div class="master-panel-head"><div><h2>Atividade recente</h2><p>Últimos eventos de negócio registrados</p></div><a href="platform-admin-master.php?view=logs">Ver logs</a></div><?php $recent=$pdo->query('SELECT l.created_at,l.actor_user_id,l.action_key,l.subject_type,l.subject_id,u.name FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_user_id ORDER BY l.created_at DESC LIMIT 8')->fetchAll(); ?><?php if(!$recent): ?><p class="master-empty-inline">Ainda não há eventos registrados.</p><?php else: ?><div class="master-activity"><?php foreach($recent as $item): ?><div><i></i><span><b><?= pmae($item['name']?:('Usuário #'.$item['actor_user_id'])) ?></b><small><?= pmae($item['action_key']) ?> · <?= pmae($item['subject_type'].' '.$item['subject_id']) ?></small></span><time><?= pmae($item['created_at']) ?> UTC</time></div><?php endforeach; ?></div><?php endif; ?></section><section class="master-panel"><div class="master-panel-head"><div><h2>Integridade e atenção</h2><p>Dados e fluxos que precisam de configuração</p></div></div><div class="master-health"><p><b><?= pma_count($pdo,"SELECT COUNT(*) FROM integration_connections WHERE status<>'active'") ?></b><span>conexões pausadas</span></p><p><b><?= pma_count($pdo,"SELECT COUNT(*) FROM platform_admin_alerts WHERE status IN ('open','investigating')") ?></b><span>alertas sob investigação</span></p><p><b><?= pma_count($pdo,"SELECT COUNT(*) FROM api_login_attempts WHERE locked_until>UTC_TIMESTAMP()") ?></b><span>bloqueios de login ativos</span></p><a href="platform-admin-master.php?view=intelligence">Abrir investigação →</a></div></section></div><?php endif; ?>
