ae($csrf) ?>"><input type="hidden" name="action" value="account_status"><input type="hidden" name="user_id" value="<?= pmae($row['user_id']) ?>"><input type="hidden" name="confirm" value="yes"><input name="reason" minlength="8" maxlength="500" placeholder="Motivo obrigatório" required><select name="status"><option value="active">Ativa</option><option value="suspended">Suspender</option><option value="blocked">Bloquear</option></select><button class="button small" type="submit" onclick="return confirm('Confirma a alteração da conta?')">Aplicar</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6">Nenhum registro encontrado.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?>
